      {screen === 'audio' && renderAudioScreen()}
      {screen === 'avatar' && renderAvatarScreen()}
      {screen === 'preview' && renderPreviewScreen()}
      {screen === 'projects' && renderProjectsScreen()}
    </SafeAreaView>
  );
}

